import{_ as d,o as a,c as e,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"服务端与授权","description":"AgoraIn v4 多区域运营、激活码、AI 额度和远程存储","frontmatter":{"title":"服务端与授权","description":"AgoraIn v4 多区域运营、激活码、AI 额度和远程存储"},"headers":[],"relativePath":"server.md","filePath":"server.md","lastUpdated":1791175383000}'),s={name:"server.md"};function i(r,t,l,n,h,c){return a(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="服务端与授权" tabindex="-1">服务端与授权 <a class="header-anchor" href="#服务端与授权" aria-label="Permalink to &quot;服务端与授权&quot;">​</a></h1><p>服务端是 AgoraIn v4 的唯一在线节点：一套部署同时服务多所机构（多区域 / 租户隔离）， 机构自助注册后由平台方颁发激活码开通。</p><h2 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h2><p>首次部署后访问站点，或直接调用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:5250/api/v4/auth/setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;username&quot;:&quot;admin&quot;,&quot;password&quot;:&quot;******&quot;,&quot;email&quot;:&quot;admin@example.com&quot;}&#39;</span></span></code></pre></div><p>初始化完成后 <code>/api/v4/setup/status</code> 返回 <code>{&quot;needsSetup&quot;:false}</code>。 管理面板登录页在未初始化时也会给出创建管理员的向导。</p><h2 id="三级编码体系" tabindex="-1">三级编码体系 <a class="header-anchor" href="#三级编码体系" aria-label="Permalink to &quot;三级编码体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前缀</th><th>名称</th><th>颁发方</th><th>用途</th></tr></thead><tbody><tr><td><code>AGRN-</code></td><td>服务器激活码</td><td>授权方（离线签发）</td><td>服务器级商业授权，绑定机器指纹、限制设备数与到期时间</td></tr><tr><td><code>AGRR-</code></td><td>区域激活码</td><td>主区域</td><td>开通 / 续期某个机构（区域）；未激活区域仅主账号可登录</td></tr><tr><td><code>AGRT-</code></td><td>AI 额度码</td><td>主区域</td><td>为机构充值平台 AI 额度（余额以人民币计价，跨模型通用）</td></tr></tbody></table><h2 id="多区域-租户-体系" tabindex="-1">多区域（租户）体系 <a class="header-anchor" href="#多区域-租户-体系" aria-label="Permalink to &quot;多区域（租户）体系&quot;">​</a></h2><ul><li><strong>注册</strong>：机构注册（<code>mode=region</code>）创建区域与主账号；家长可凭邀请码加入（<code>mode=join</code>）</li><li><strong>登录</strong>：<code>用户名@区域</code>（主区域为 <code>@manager</code>；不带 <code>@</code> 按主区域处理）</li><li><strong>数据隔离</strong>：班级、学生、打卡、课时、课表、试卷、成绩等全部按区域过滤</li><li><strong>区域功能开关</strong>：AI 功能 / 阅卷与出分 / 答题卡识别与批改 / 设备注册 / 课表管理 / 子用户 / 家长邀请</li><li><strong>账号管理</strong>：区域管理页可查看本区域用户并禁用 / 启用账号</li></ul><h2 id="ai-与额度" tabindex="-1">AI 与额度 <a class="header-anchor" href="#ai-与额度" aria-label="Permalink to &quot;AI 与额度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>计费</th></tr></thead><tbody><tr><td>机构使用平台 AI</td><td>按实际 token 扣减额度（DeepSeek / Mimo 按模型折算，余额以元计价）</td></tr><tr><td>机构自配 AI 密钥</td><td>不受平台额度限制，费用由机构自行承担</td></tr><tr><td>本地识别（客观题涂卡、填空手写）</td><td><strong>零 token</strong>，不产生任何费用</td></tr></tbody></table><p>配置优先级：<code>appsettings</code> 默认 → 主区域全局覆盖 → 区域独立配置（最高）。 每个机构都可以在「AI 设置」中配置自己的地址、密钥、模型与提示词模板，或一键清除恢复平台默认。</p><div class="warning custom-block"><p class="custom-block-title">图像外发</p><p>「AI 图像外发」开关关闭后，平台不会向第三方大模型发送任何作答图像， 主观题自动转为教师人工批改。该开关按机构控制。</p></div><h2 id="加密远程存储" tabindex="-1">加密远程存储 <a class="header-anchor" href="#加密远程存储" aria-label="Permalink to &quot;加密远程存储&quot;">​</a></h2><ul><li>答题卡原图与教学资料使用 <strong>AES-256-GCM</strong> 认证加密（被篡改的文件读取时会被拒绝）</li><li>通过 WebDAV 上传远程磁盘，路径形如 <code>{根目录}/agorain/{区域}/{类别}/</code></li><li>服务器只保留<strong>按需缓存</strong>（LRU），且只淘汰已确认上传成功的本机副本</li><li>远程不可用时自动排队补传，不影响本地使用</li></ul><h2 id="邮件-smtp" tabindex="-1">邮件（SMTP） <a class="header-anchor" href="#邮件-smtp" aria-label="Permalink to &quot;邮件（SMTP）&quot;">​</a></h2><p>用于注册验证码与忘记密码。在「设置」中配置服务器、端口、发件人、密码与 SSL， 并可直接发送测试邮件。服务端内置发信频率限制（同一邮箱 / IP 的冷却与每日上限）。</p><h2 id="安装包分发-下载中心" tabindex="-1">安装包分发（下载中心） <a class="header-anchor" href="#安装包分发-下载中心" aria-label="Permalink to &quot;安装包分发（下载中心）&quot;">​</a></h2><p>官网的下载按钮指向平台自己的分发接口，安装包存放在数据目录的 <code>downloads/</code> 下：</p><table tabindex="0"><thead><tr><th>接口</th><th>鉴权</th><th>用途</th></tr></thead><tbody><tr><td><code>GET /api/v4/downloads</code></td><td>匿名</td><td>清单：名称 / 平台 / 版本 / 大小 / SHA256 / 下载地址</td></tr><tr><td><code>GET /api/v4/downloads/{slug}</code></td><td>匿名</td><td>下载文件（支持单段 Range 断点续传）</td></tr><tr><td><code>HEAD /api/v4/downloads/{slug}</code></td><td>匿名</td><td>只取大小与指纹</td></tr><tr><td><code>GET /api/v4/downloads/guard</code></td><td>匿名</td><td>反多线程策略与当前占用快照（排障）</td></tr><tr><td><code>POST /api/v4/downloads/{slug}</code></td><td>运营方</td><td>上传 / 覆盖安装包（multipart，<code>name</code>/<code>platform</code>/<code>version</code>/<code>note</code>/<code>order</code> 可选）</td></tr><tr><td><code>DELETE /api/v4/downloads/{slug}</code></td><td>运营方</td><td>删除安装包</td></tr></tbody></table><ul><li>官网按钮用的固定 slug：桌面端 <code>desktop-win-x64</code>、移动端 <code>android-apk</code></li><li>直接把文件放进 <code>downloads/</code> 也能用（slug 取文件名去扩展名）；<code>downloads/manifest.json</code> 负责展示名、版本与排序</li></ul><p><strong>反多线程下载</strong>（默认开启，<code>appsettings.json</code> 的 <code>Downloads</code> 段可调）：</p><table tabindex="0"><thead><tr><th>策略</th><th>默认值</th><th>作用</th></tr></thead><tbody><tr><td>同一 IP 并发连接</td><td>3</td><td>超过直接 429，防止开几十条连接抢带宽</td></tr><tr><td>同一 IP 对同一文件并发</td><td>2</td><td>分段下载器叠加不出速度</td></tr><tr><td>每分钟 Range 请求</td><td>6 次</td><td>超预算按 IP+文件临时封禁（默认 5 分钟）</td></tr><tr><td>单连接带宽上限</td><td>8192 KB/s</td><td>多线程总速度被&quot;每线程上限 × 允许并发&quot;封顶</td></tr></tbody></table><p>正常浏览器/手机下载只占 1 条连接、至多 1~2 次 Range 请求，不受影响。</p><h2 id="更新检查" tabindex="-1">更新检查 <a class="header-anchor" href="#更新检查" aria-label="Permalink to &quot;更新检查&quot;">​</a></h2><p>服务端代理 GitHub Releases 查询版本，客户端「设置 → 更新检查」可查看新版本并跳转下载 （30 分钟成功缓存 / 5 分钟失败缓存）。</p><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/deploy.html">部署指南</a> · <a href="/api.html">API 文档</a> · <a href="/guide.html">快速开始</a></li><li>历史版本：<a href="/v3.2/server.html">v3.2 服务端文档</a></li></ul>`,29)])])}const k=d(s,[["render",i]]);export{u as __pageData,k as default};
